def main():
    DOCS.mkdir(exist_ok=True)
    cases=[]
    text=['# Especificaciones de casos de uso', '', 'Autor: Equipo FashionStore. Fecha de especificación: 22 de octubre de 2026.', '', 'Las fichas expresan comportamiento requerido. El estado de implementación y de prueba se registra en la matriz, sin inferirlo del prototipo P1.', '']
    diagramdir=DOCS/'diagramas'/'casos_uso'; diagramdir.mkdir(parents=True,exist_ok=True)
    protos=DOCS/'prototipos';protos.mkdir(exist_ok=True)
    matrix=['# Matriz de trazabilidad', '', '| CU | Antecedente P1 | Fuente | Componente esperado | Prueba de aceptación | Estado | Evidencia |','|---|---|---|---|---|---|---|']
    for i,row in enumerate(CASES,1):
        name,actors,platform,previous,fields,flow,alternates,outcome=row
        cid=f'CU-{i:02d}'
        case=dict(id=cid,nombre=name,actores=actors,plataforma=platform,antecedente=previous,datos=fields,flujo=flow.split(';'),alternativos=alternates.split(';'),postcondicion=outcome,estado='especificado')
        cases.append(case)
        text += [f'## {cid} {name}', '', f'**Actor:** {actors}. **Plataforma:** {platform}. **Antecedente P1:** {previous}.', '', f'**Objetivo:** {outcome}.', '', f'**Precondiciones:** empresa identificada y activa; permisos vigentes para operaciones privadas; referencias pertenecientes a la misma empresa. Para registro offline, snapshot y sesión previamente habilitados.', '',f'**Disparador:** el actor solicita {name.lower()}.', '', f'**Datos:** {fields}.', '', '**Flujo principal**', '']
        text += [f'{n}. {step}.' for n,step in enumerate(case['flujo'],1)]
        text += ['', '**Flujos alternativos**', '']+[f'- {step}.' for step in case['alternativos']]
        text += ['',f'**Postcondición:** {outcome}.', '', '**Aceptación:** ejecutar el flujo con datos de la empresa A, comprobar el resultado y repetir una petición con referencias de B para verificar la restricción cuando corresponda. Ejecutar cada alternativa y conservar el resultado real; no basta una captura de la pantalla inicial.', '',f'**Prototipo:** `prototipos/{cid}.svg`. **Diagrama:** `diagramas/casos_uso/{cid}.puml`.', '']
        matrix.append(f'| {cid} | {previous} | Examen P2 y reglas capítulo II | Backend y {platform} | CP-{i:02d}: principal y alternativas de la ficha | especificado | pendiente de ejecución |')
        (diagramdir/f'{cid}.puml').write_text(f'@startuml\nleft to right direction\nactor "{actors}" as Actor\nrectangle "FashionStore SaaS" {{\nusecase "{cid}\\n{name}" as UC\n}}\nActor --> UC\n@enduml\n',encoding='utf-8')
        labels=fields.split(', ')[:5]
        content=''.join(f'<text x="65" y="{165+j*62}" fill="#39463b" font-size="16">{escape(label.capitalize())}</text><rect x="65" y="{175+j*62}" width="650" height="25" rx="3" fill="#f3f2ed" stroke="#bcc4bb"/>' for j,label in enumerate(labels))
        svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="780" height="620" viewBox="0 0 780 620"><rect width="780" height="620" fill="#faf9f4"/><text x="40" y="45" font-family="Georgia" font-size="26" fill="#153a29">FashionStore</text><text x="40" y="80" font-size="12">Prototipo de requisitos {cid} · {escape(platform)}</text><text x="40" y="120" font-family="Georgia" font-size="21">{escape(name)}</text>{content}<rect x="65" y="525" width="190" height="42" rx="4" fill="#153a29"/><text x="95" y="552" fill="white" font-size="16">Continuar</text><text x="65" y="600" font-size="12">Boceto de requisitos; no acredita implementación ni resultados.</text></svg>'
        (protos/f'{cid}.svg').write_text(svg,encoding='utf-8')
    (DOCS/'casos_de_uso.json').write_text(json.dumps(cases,ensure_ascii=False,indent=2),encoding='utf-8')
    (DOCS/'03_casos_de_uso.md').write_text('\n'.join(text),encoding='utf-8')
    (DOCS/'TRAZABILIDAD.md').write_text('\n'.join(matrix)+'\n',encoding='utf-8')
    print(f'{len(cases)} fichas, diagramas y prototipos generados; estado especificado.')

if __name__=='__main__':main()
